/*
 * A118533  Start with 1 and repeatedly reverse the digits and add 16 to get
 *          the next term.
 * https://oeis.org/A118533
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   reverse_decimal
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula:   a(1) = 1
 *            a(n) = rev_decimal(a(n‑1)) + 16   for n > 1
 *
 * The sequence is generated by taking the previous term,
 * reversing its decimal digits, and adding 16.
 * This implementation works for any seq_t that can hold
 * the value (uint8_t, uint16_t, uint32_t, uint64_t, __int128,
 * or an arbitrary‑precision type).
 */
#include <stdint.h>
#include "../utils/reverse_decimal.h"

seq_t a(idx_t n)
{
    /* Offset starts at 1. For n < 1 we return 1 to keep behavior defined. */
    if (n <= 1)
        return (seq_t)1;

    seq_t cur = (seq_t)1;

    /* Iterate n-1 times to reach a(n). */
    for (idx_t i = 1; i < n; ++i)
    {
        cur = reverse_decimal(cur) + (seq_t)16;
    }

    return cur;
}
